async function fetchPlausibleAggregateStats(siteId, apiKey) {
  const url = `https://plausible.io/api/v1/stats/aggregate?site_id=${encodeURIComponent(siteId)}&period=30d&metrics=pageviews,visitors,bounce_rate`;
  const response = await fetch(url, {
    headers: {
      'Authorization': `Bearer ${apiKey}`
    }
  });
  if (!response.ok) {
    throw new Error(`Plausible API error: ${response.status} ${response.statusText}`);
  }
  return await response.json();
}
